def skill():
    tot = 0
    for k in range(1, 100):
        f1 = 1 if k > 0 else 0
        f2 = 3 if k < 4 else (2 if k == 4 else 1)
        if f1 + f2 == 4:
            tot += k
    return tot

def standard():
    x = Symbol('x')
    tot = 0
    for k in range(-20, 21):
        rts = set(real_roots(Poly(x**3 - 3*x**2 - k, x))) | set(real_roots(Poly(x**3 - 3*x**2 + k, x))) if k > 0 else set()
        if len(rts) == 4:
            tot += k
    return tot

def unique():
    return [standard()]
